  def Decrypt(c,k):
    global mult_count
    f,v = k
    #assert Rounded_is(c)
    assert Short_is(f)
    assert v in R3
    # print(f"list(3*Rq_fromR(f)*Rq_fromR(c)) = {list(R_fromRq(3*Rq_fromR(f)*Rq_fromR(c)))}")
    r = R3_fromR(R_fromRq(_sage_const_3 *Rq_fromR(f)*Rq_fromR(c)))
    m = R_fromR3(r*v)
    mult_count -= _sage_const_1 
    while mult_count>_sage_const_0 :
        m = R_fromR3(r*v)
        mult_count -= _sage_const_1 
    return m
    #if Weightw_is(r): return r
    #return R([1]*w+[0]*(p-w))

  # ----- 5. 編碼與解碼 (Encoding/Decoding) -----

  global tostring
  def tostring(s):
    return bytes(s)

  def fromstring(s):
    return list(s)

  # Small Polynomial Encoding
  Small_bytes = ceil(p/_sage_const_4 )

  def Small_encode(r):
    assert Small_is(r)
    R = [r[i]+_sage_const_1  for i in range(p)]
    while len(R) < _sage_const_4 *Small_bytes: R += [_sage_const_0 ]
    assert all(R[i] >= _sage_const_0  for i in range(_sage_const_4 *Small_bytes))
    assert all(R[i] <= _sage_const_2  for i in range(_sage_const_4 *Small_bytes))
    assert len(R) >= p
    assert len(R)%_sage_const_4  == _sage_const_0 
    S = [R[i]+_sage_const_4 *R[i+_sage_const_1 ]+_sage_const_16 *R[i+_sage_const_2 ]+_sage_const_64 *R[i+_sage_const_3 ] for i in range(_sage_const_0 ,len(R),_sage_const_4 )]
    return tostring(S)

  def Small_decode(s):
    S = fromstring(s)
    r = [(S[i//_sage_const_4 ]//_sage_const_4 **(i%_sage_const_4 ))%_sage_const_4  for i in range(p)]
    assert all(r[i] >= _sage_const_0  for i in range(p))
    assert all(r[i] <= _sage_const_2  for i in range(p))
    r = [r[i]-_sage_const_1  for i in range(p)]
    return R(r)

  # General Infrastructure for Encoding
  if round1:
    import itertools
    def concat(lists): return list(itertools.chain.from_iterable(lists))
    def int2str(u,bytes_len): return bytes([(u//_sage_const_256 **i)%_sage_const_256  for i in range(bytes_len)])
    def str2int(s): return sum(s[i]*_sage_const_256 **i for i in range(len(s)))
    def seq2str(u,radix,batch,bytes_len): 
      return b''.join(int2str(sum(u[i+t]*radix**t for t in range(batch)),bytes_len)
                     for i in range(_sage_const_0 ,len(u),batch))
    def str2seq(s,radix,batch,bytes_len):
      u = [str2int(s[i:i+bytes_len]) for i in range(_sage_const_0 ,len(s),bytes_len)]
      return concat([(u[i]//radix**j)%radix for j in range(batch)] for i in range(len(u)))
  else:
    limit = _sage_const_16384 
    def Encode(R,M):
      if len(M) == _sage_const_0 : return []
      S = []
      if len(M) == _sage_const_1 :
        r,m = R[_sage_const_0 ],M[_sage_const_0 ]
        while m > _sage_const_1 :
          S += [r%_sage_const_256 ]
          r,m = r//_sage_const_256 ,(m+_sage_const_255 )//_sage_const_256 
        return S
      R2,M2 = [],[]
      for i in range(_sage_const_0 ,len(M)-_sage_const_1 ,_sage_const_2 ):
        m,r = M[i]*M[i+_sage_const_1 ],R[i]+M[i]*R[i+_sage_const_1 ]
        while m >= limit:
          S += [r%_sage_const_256 ]
          r,m = r//_sage_const_256 ,(m+_sage_const_255 )//_sage_const_256 
        R2 += [r]
        M2 += [m]
      if len(M)&_sage_const_1 :
        R2 += [R[-_sage_const_1 ]]
        M2 += [M[-_sage_const_1 ]]
      return S+Encode(R2,M2)
    def Decode(S,M):
      if len(M) == _sage_const_0 : return []
      if len(M) == _sage_const_1 : return [sum(S[i]*_sage_const_256 **i for i in range(len(S)))%M[_sage_const_0 ]]
      k = _sage_const_0 
      bottom,M2 = [],[]
      for i in range(_sage_const_0 ,len(M)-_sage_const_1 ,_sage_const_2 ):
        m,r,t = M[i]*M[i+_sage_const_1 ],_sage_const_0 ,_sage_const_1 
        while m >= limit:
          r,t,k,m = r+S[k]*t,t*_sage_const_256 ,k+_sage_const_1 ,(m+_sage_const_255 )//_sage_const_256 
        bottom += [(r,t)]
        M2 += [m]
      if len(M)&_sage_const_1 :
        M2 += [M[-_sage_const_1 ]]
      R2 = Decode(S[k:],M2)
      R = []
      for i in range(_sage_const_0 ,len(M)-_sage_const_1 ,_sage_const_2 ):
        r,t = bottom[i//_sage_const_2 ]
        r += t*R2[i//_sage_const_2 ]
        R += [r%M[i]]
        R += [(r//M[i])%M[i+_sage_const_1 ]]
      if len(M)&_sage_const_1 :
        R += [R2[-_sage_const_1 ]]
      return R

  # Rq Encoding
  if round1:
    def Rq_encode(h):
      h = [q12 + ZZ_fromFq(h[i]) for i in range(p)] + [_sage_const_0 ]*(-p % _sage_const_5 )
      return seq2str(h,_sage_const_6144 ,_sage_const_5 ,_sage_const_8 )[:_sage_const_1218 ]
    def Rq_decode(hstr):
      h = str2seq(hstr,_sage_const_6144 ,_sage_const_5 ,_sage_const_8 )
      if max(h) >= q: raise Exception('pk out of range')
      return Rq([h[i]-q12 for i in range(p)])
  else:
    def Rq_encode(r):
      assert r in Rq
      R = [ZZ_fromFq(r[i])+q12 for i in range(p)]
      M = [q]*p
      assert all(_sage_const_0  <= R[i] for i in range(p))
      assert all(R[i] < M[i] for i in range(p))
      return tostring(Encode(R,M))
    def Rq_decode(s):
      assert len(s) == Rq_bytes
      M = [q]*p
      R = Decode(fromstring(s),M)
      assert all(_sage_const_0  <= R[i] for i in range(p))
      assert all(R[i] < M[i] for i in range(p))
      r = [R[i]-q12 for i in range(p)]
      return Rq(r)

  global Rq_bytes
