  def get_log_q():
    """計算需要的位元數 l = ceil(log2(q))"""
    return Integer(q).nbits()
  
  def BitDecompose_poly(A):
    """
    輸入: A (必須是 R 中的多項式, Integer Polynomial)
    輸出: [p0, p1, ..., pl-1] (每個 pi 都是 R 中的多項式)
    """
    # 1. 取得位元長度 l = ceil(log2(q))
    # 這裡使用 Integer(q) 確保可以呼叫 nbits 方法
    l = Integer(q).nbits()

    # 2. 驗證輸入型別 (根據您的要求)
    # 如果 A 不是 R 的元素，這裡會報錯，或者您可以選擇在此處強制轉型 A = R(A)
    if A.parent() != R:
        # 為了容錯，如果傳進來的是 Rq，我們嘗試轉回 R
        # 但如果傳入的是 list 或 int，這行會報錯
        try:
            A = R(A)
        except TypeError:
            raise TypeError(f"BitDecompose 輸入必須是 R 中的多項式，目前是: {A.parent()}")

    # 3. 係數正規化 (Normalization)
    # 這是最關鍵的一步！
    # R 中的多項式係數可能是負的 (例如 -1, 0, 1)。
    # 在進行位元分解前，我們必須將其映射到 [0, q-1] 的正整數區間。
    # Python 的 % 運算子對負數處理得很好: -1 % 4591 = 4590
    raw_coeffs = list(A)
    coeffs = [int(c) % q for c in raw_coeffs]
    
    # 補齊長度到 p (Sage 有時會省略高次項的 0)
    if len(coeffs) < p:
        coeffs += [_sage_const_0 ] * (p - len(coeffs))
    
    # 4. 進行位元分解
    # 我們直接建立 l 個係數列表，最後再轉成多項式
    poly_list = []
    
    for i in range(l):
        # 對於第 i 層，取出所有係數的第 i 個 bit
        # bit_row 是一個長度為 p 的整數列表 (內容只有 0 或 1)
        bit_row = [(c >> i) & _sage_const_1  for c in coeffs]
        
        # 5. [關鍵] 將列表轉為 R (整數環) 的多項式
        # 這確保了後續與 evk (如果 evk 也是 R) 運算時不會有型別衝突
        poly_in_R = R(bit_row)
        poly_list.append(poly_in_R)
        
    return poly_list

  def PowerOf2_poly(B):
    """
    輸入: 多項式 B (在 R 中)
    輸出: 多項式向量 [B, 2B, 4B, ..., 2^(l-1)B]
    """
    assert B in R

    l = get_log_q()
    
    # 生成 2 的冪次列表
    result_vector = []
    for i in range(l):
        scale = _sage_const_2 **i
        result_vector.append(R_fromRq(Rq_fromR(B * scale)))
        
    return result_vector

  def Vector_DotProduct(A, B):
    """
    計算兩個多項式向量的內積
    A, B: List of polynomials in R
    回傳: Single polynomial in R
    """
    if len(A) != len(B):
        raise ValueError("向量長度不一致")
    return sum(a * b for a, b in zip(A, B))
  
  def KeySwitch(c_mult_tilde_D, evk):
    return R_fromRq(Vector_DotProduct(c_mult_tilde_D, evk))
  
  global homomorphic_mult
  def homomorphic_mult(c_1,c_2,evk):

    # 1. 計算 P(c1) 和 P(c2)
    # vec1 和 vec2 都是長度為 l 的向量
    vec1 = PowerOf2_poly(c_1)
    vec2 = PowerOf2_poly(c_2)
    
    c_tilde = []
    
    # 2. 計算張量積 (Tensor Product)
    # 數學上是對每一對元素做乘法: v1[i] * v2[j]
    # 我們將 l x l 的矩陣展平為長度 l^2 的向量
    c_tilde = TensorProduct_poly(vec1, vec2)
    
    c_mult_tilde_B = []
    # 3. 使用 Evaluation Key 進行 Key Switching
    for c in c_tilde:
        for cB in BitDecompose_poly(c):
            c_mult_tilde_B.append(cB)
    

    c_mult = KeySwitch(c_mult_tilde_B, evk)
    return c_mult

